582 :         stopTolUpX = 1e3 * max(insigma);
583 :         stopTolX = 1e-11 * max(insigma);
584 :         stopTolFun = 1e-12;
585 :         stopTolHistFun = 1e-13;
586 : 
587 :         // initialize selection strategy parameters
588 :         mu = lambda / 2; // number of parents/points for recombination
589 :         logMu2 = Math.log(mu + 0.5);
590 :         weights = log(sequence(1, mu, 1)).scalarMultiply(-1.).scalarAdd(logMu2);
591 :         double sumw = 0;
592 :         double sumwq = 0;
593 :         for (int i = 0; i < mu; i++) {
594 :             double w = weights.getEntry(i, 0);
595 :             sumw += w;
596 :             sumwq += w * w;
597 :         }
598 :         weights = weights.scalarMultiply(1. / sumw);
599 :         mueff = sumw * sumw / sumwq; // variance-effectiveness of sum w_i x_i
600 : 
601 :         // initialize dynamic strategy parameters and constants
602 :         cc = (4. + mueff / dimension) /
603 :                 (dimension + 4. + 2. * mueff / dimension);
604 :         cs = (mueff + 2.) / (dimension + mueff + 3.);
605 :         damps = (1. + 2. * Math.max(0, Math.sqrt((mueff - 1.) /
606 :                 (dimension + 1.)) - 1.)) *
607 :                 Math.max(0.3, 1. - dimension /
608 :                         (1e-6 + Math.min(maxIterations, getMaxEvaluations() /
609 :                                 lambda))) + cs; // minor increment
610 :         ccov1 = 2. / ((dimension + 1.3) * (dimension + 1.3) + mueff);
611 :         ccovmu = Math.min(1 - ccov1, 2. * (mueff - 2. + 1. / mueff) /
612 :                 ((dimension + 2.) * (dimension + 2.) + mueff));
613 :         ccov1Sep = Math.min(1, ccov1 * (dimension + 1.5) / 3.);
614 :         ccovmuSep = Math.min(1 - ccov1, ccovmu * (dimension + 1.5) / 3.);
615 :         chiN = Math.sqrt(dimension) *
616 :                 (1. - 1. / (4. * dimension) + 1 / (21. * dimension * dimension));
617 :         // intialize CMA internal values - updated each generation
618 :         xmean = MatrixUtils.createColumnRealMatrix(guess); // objective
619 :                                                            // variables
